using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Stops a poll sent on behalf of a business account; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.BusinessMessage> StopBusinessPollAsync(string businessConnectionId = default, long chatId = default, long messageId = default, ReplyMarkup replyMarkup = default)
    {

           using var activity =  StartCallActivity("StopBusinessPollAsync", typeof(StopBusinessPoll).FullName ?? "StopBusinessPollAsync");

           try
           {
             return client.StopBusinessPollAsync(businessConnectionId, chatId, messageId, replyMarkup);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
